-- H2 fixture for trade dashboard regression tests. Keep cost snapshot types aligned with MySQL.
CREATE TABLE IF NOT EXISTS "trade_order"
(
    "id"                      bigint   NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "no"                      varchar  NOT NULL,
    "type"                    int      NOT NULL,
    "terminal"                int      NOT NULL,
    "user_id"                 bigint   NOT NULL,
    "user_ip"                 varchar  NOT NULL,
    "user_remark"             varchar,
    "address_verification"    varchar,
    "status"                  int      NOT NULL,
    "product_count"           int      NOT NULL,
    "cancel_type"             int,
    "remark"                  varchar,
    "comment_status"          boolean,
    "brokerage_user_id"       bigint,
    "pay_status"              bit      NOT NULL,
    "pay_time"                datetime,
    "finish_time"             datetime,
    "cancel_time"             datetime,
    "total_price"             int      NULL,
    "order_price"             int      NULL,
    "discount_price"          int      NOT NULL,
    "delivery_price"          int      NOT NULL,
    "adjust_price"            int      NOT NULL,
    "pay_price"               int      NOT NULL,
    "delivery_type"           int      NOT NULL,
    "pay_order_id"            bigint,
    "pay_channel_code"        varchar,
    "delivery_template_id"    bigint,
    "logistics_id"            bigint,
    "logistics_no"            varchar,
    "delivery_time"           datetime,
    "receive_time"            datetime,
    "receiver_name"           varchar  NOT NULL,
    "receiver_mobile"         varchar  NOT NULL,
    "receiver_area_id"        int      NOT NULL,
    "receiver_post_code"      int,
    "receiver_detail_address" varchar  NOT NULL,
    "pick_up_store_id"        long     NULL,
    "pick_up_verify_code"     varchar  NULL,
    "refund_status"           int      NULL,
    "refund_price"            int      NULL,
    "after_sale_status"       int      NULL,
    "coupon_id"               bigint   NOT NULL,
    "coupon_price"            int      NOT NULL,
    "use_point"               int      NULL,
    "point_price"             int      NOT NULL,
    "give_point"              int      NULL,
    "refund_point"            int      NULL,
    "vip_price"               int      NULL,
    "give_coupons_map"        varchar  NULL,
    "seckill_activity_id"     long     NULL,
    "bargain_activity_id"     long     NULL,
    "bargain_record_id"       long     NULL,
    "combination_activity_id" long     NULL,
    "combination_head_id"     long     NULL,
    "combination_record_id"   long     NULL,
    "creator"                 varchar           DEFAULT '',
    "create_time"             datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"                 varchar           DEFAULT '',
    "update_time"             datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"                 bit      NOT NULL DEFAULT FALSE,
    "tenant_id"               bigint   NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT '交易订单表';

CREATE TABLE IF NOT EXISTS "trade_order_item"
(
    "id"                bigint   NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id"           bigint   NOT NULL,
    "order_id"          bigint   NOT NULL,
    "cart_id"           int      NULL,
    "registry_id"       bigint,
    "registry_item_id"  bigint,
    "spu_id"            bigint   NOT NULL,
    "spu_name"          varchar  NOT NULL,
    "sku_id"            bigint   NOT NULL,
    "properties"        varchar,
    "pic_url"           varchar,
    "count"             int      NOT NULL,
    "comment_status"    boolean  NULL,
    "price"             int      NOT NULL,
    "cost_price"        bigint,
    "cost_estimated"    bit      DEFAULT FALSE,
    "discount_price"    int      NOT NULL,
    "delivery_price"    int      NULL,
    "adjust_price"      int      NULL,
    "pay_price"         int      NOT NULL,
    "coupon_price"      int      NULL,
    "point_price"       int      NULL,
    "use_point"         int      NULL,
    "give_point"        int      NULL,
    "vip_price"         int      NULL,
    "after_sale_id"     long     NULL,
    "after_sale_status" int      NOT NULL,
    "creator"           varchar           DEFAULT '',
    "create_time"       datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"           varchar           DEFAULT '',
    "update_time"       datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"           bit      NOT NULL DEFAULT FALSE,
    "tenant_id"         bigint   NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT '交易订单明细表';

CREATE TABLE IF NOT EXISTS "trade_after_sale"
(
    "id"             bigint   NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "no"             varchar  NOT NULL,
    "status"         int      NOT NULL,
    "type"           int      NOT NULL,
    "way"            int      NOT NULL,
    "user_id"        bigint   NOT NULL,
    "apply_reason"   varchar  NOT NULL,
    "apply_description" varchar,
    "apply_pic_urls" varchar,
    "order_id"       bigint   NOT NULL,
    "order_no"       varchar  NOT NULL,
    "order_item_id"  bigint   NOT NULL,
    "spu_id"         bigint   NOT NULL,
    "spu_name"       varchar  NOT NULL,
    "sku_id"         bigint   NOT NULL,
    "properties"     varchar,
    "pic_url"        varchar,
    "count"          int      NOT NULL,
    "audit_time"     varchar,
    "audit_user_id"  bigint,
    "audit_reason"   varchar,
    "refund_price"   int      NOT NULL,
    "pay_refund_id"  bigint,
    "refund_time"    varchar,
    "logistics_id"   bigint,
    "logistics_no"   varchar,
    "delivery_time"  varchar,
    "receive_time"   varchar,
    "receive_reason" varchar,
    "creator"        varchar           DEFAULT '',
    "create_time"    datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"        varchar           DEFAULT '',
    "update_time"    datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"        bit      NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id")
) COMMENT '交易售后表';

CREATE TABLE IF NOT EXISTS "trade_after_sale_log"
(
    "id"            bigint   NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id"       bigint   NOT NULL,
    "user_type"     int      NOT NULL,
    "after_sale_id" bigint   NOT NULL,
    "order_id"      bigint   NOT NULL,
    "order_item_id" bigint   NOT NULL,
    "before_status" int,
    "after_status"  int      NOT NULL,
    "content"       varchar  NOT NULL,
    "creator"       varchar           DEFAULT '',
    "create_time"   datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"       varchar           DEFAULT '',
    "update_time"   datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"       bit      NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id")
) COMMENT '交易售后日志';

CREATE TABLE IF NOT EXISTS "trade_brokerage_user"
(
    "id"                bigint   NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "bind_user_id"      bigint   NOT NULL,
    "bind_user_time"    varchar,
    "brokerage_enabled" bit      NOT NULL,
    "brokerage_time"    varchar,
    "price"             int      NOT NULL,
    "frozen_price"      int      NOT NULL,
    "creator"           varchar           DEFAULT '',
    "create_time"       datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"           varchar           DEFAULT '',
    "update_time"       datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"           bit      NOT NULL DEFAULT FALSE,
    "tenant_id"         bigint   NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
) COMMENT '分销用户';
CREATE TABLE IF NOT EXISTS "trade_brokerage_record"
(
    "id"            bigint   NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id"       bigint   NOT NULL,
    "biz_id"        varchar  NOT NULL,
    "biz_type"      varchar  NOT NULL,
    "title"         varchar  NOT NULL,
    "price"         int      NOT NULL,
    "total_price"   int      NOT NULL,
    "description"   varchar  NOT NULL,
    "status"        varchar  NOT NULL,
    "frozen_days"   int      NOT NULL,
    "unfreeze_time" varchar,
    "source_user_level" int,
    "source_user_id"    bigint,
    "creator"       varchar           DEFAULT '',
    "create_time"   datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"       varchar           DEFAULT '',
    "update_time"   datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"       bit      NOT NULL DEFAULT FALSE,
    "tenant_id" bigint not null default '0',
    PRIMARY KEY ("id")
) COMMENT '佣金记录';
CREATE TABLE IF NOT EXISTS "trade_brokerage_withdraw"
(
    "id"                  int      NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id"             bigint   NOT NULL,
    "price"               int      NOT NULL,
    "fee_price"           int      NOT NULL,
    "total_price"         int      NOT NULL,
    "type"                varchar  NOT NULL,
    "name"                varchar,
    "account_no"          varchar,
    "bank_name"           varchar,
    "bank_address"        varchar,
    "account_qr_code_url" varchar,
    "status"              varchar  NOT NULL,
    "audit_reason"        varchar,
    "audit_time"          varchar,
    "remark"              varchar,
    "creator"             varchar           DEFAULT '',
    "create_time"         datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"             varchar           DEFAULT '',
    "update_time"         datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"             bit      NOT NULL DEFAULT FALSE,
    "tenant_id" bigint not null default '0',
    PRIMARY KEY ("id")
) COMMENT '佣金提现';

CREATE TABLE IF NOT EXISTS "trade_delivery_express"
(
    "id"          int      NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "code"        varchar  NULL,
    "name"        varchar,
    "logo"        varchar  NULL,
    "sort"        int      NOT NULL,
    "status"      int      NOT NULL,
    "creator"     varchar           DEFAULT '',
    "create_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"     varchar           DEFAULT '',
    "update_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"     bit      NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id")
) COMMENT '佣金提现';

CREATE TABLE IF NOT EXISTS "trade_carrier"
(
    "id"                bigint       NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "tenant_id"         bigint       NOT NULL,
    "code"              varchar(32)  NOT NULL,
    "name"              varchar(128) NOT NULL,
    "country_codes"     varchar(32)  NOT NULL,
    "legacy_express_id" bigint,
    "status"            tinyint      NOT NULL DEFAULT 0,
    "creator"           varchar(64)  NOT NULL DEFAULT '',
    "create_time"       datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"           varchar(64)  NOT NULL DEFAULT '',
    "update_time"       datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted"           bit          NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_carrier_code" UNIQUE ("tenant_id", "code", "deleted")
);

CREATE TABLE IF NOT EXISTS "trade_logistics_provider"
(
    "id"           bigint       NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "tenant_id"    bigint       NOT NULL,
    "code"         varchar(32)  NOT NULL,
    "name"         varchar(128) NOT NULL,
    "capabilities" varchar(512) NOT NULL,
    "status"       tinyint      NOT NULL DEFAULT 0,
    "creator"      varchar(64)  NOT NULL DEFAULT '',
    "create_time"  datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"      varchar(64)  NOT NULL DEFAULT '',
    "update_time"  datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted"      bit          NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_provider_code" UNIQUE ("tenant_id", "code", "deleted")
);

CREATE TABLE IF NOT EXISTS "trade_shipment"
(
    "id"                      bigint      NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "tenant_id"               bigint      NOT NULL,
    "order_id"                bigint      NOT NULL,
    "shipment_no"             varchar(32) NOT NULL,
    "shipment_type"           varchar(20) NOT NULL,
    "status"                  varchar(32) NOT NULL,
    "origin_country"          char(2)     NOT NULL,
    "destination_country"     char(2)     NOT NULL,
    "origin_timezone"         varchar(64) NOT NULL,
    "destination_timezone"    varchar(64) NOT NULL,
    "warehouse_id"            bigint      NOT NULL,
    "provider_id"             bigint,
    "estimated_delivery_at"   datetime,
    "delivered_at"            datetime,
    "last_event_occurred_at"  datetime(6),
    "last_event_status_priority" int,
    "last_event_id"           bigint,
    "version"                 int         NOT NULL DEFAULT 0,
    "creator"                 varchar(64) NOT NULL DEFAULT '',
    "create_time"             datetime    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"                 varchar(64) NOT NULL DEFAULT '',
    "update_time"             datetime    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted"                 bit         NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_shipment_no" UNIQUE ("tenant_id", "shipment_no", "deleted"),
    CONSTRAINT "chk_shipment_origin_country" CHECK ("origin_country" IN ('US', 'CA')),
    CONSTRAINT "chk_shipment_destination_country" CHECK ("destination_country" IN ('US', 'CA')),
    CONSTRAINT "chk_shipment_domestic" CHECK ("destination_country" = "origin_country")
);

CREATE TABLE IF NOT EXISTS "trade_shipment_item"
(
    "id"            bigint        NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "tenant_id"     bigint        NOT NULL,
    "shipment_id"   bigint        NOT NULL,
    "order_item_id" bigint        NOT NULL,
    "sku_id"        bigint        NOT NULL,
    "quantity"      decimal(24,6) NOT NULL,
    "creator"       varchar(64)   NOT NULL DEFAULT '',
    "create_time"   datetime      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"       varchar(64)   NOT NULL DEFAULT '',
    "update_time"   datetime      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted"       bit           NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_shipment_item" UNIQUE ("tenant_id", "shipment_id", "order_item_id", "deleted"),
    CONSTRAINT "chk_shipment_item_quantity" CHECK ("quantity" > 0)
);

CREATE TABLE IF NOT EXISTS "trade_shipment_package"
(
    "id"              bigint        NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "tenant_id"       bigint        NOT NULL,
    "shipment_id"     bigint        NOT NULL,
    "package_no"      varchar(32)   NOT NULL,
    "package_type"    varchar(20)   NOT NULL,
    "carrier_id"      bigint,
    "tracking_number" varchar(64),
    "weight"          decimal(18,6),
    "weight_unit"     varchar(4),
    "length"          decimal(18,6),
    "width"           decimal(18,6),
    "height"          decimal(18,6),
    "dimension_unit"  varchar(4),
    "status"          varchar(32)   NOT NULL,
    "last_event_occurred_at" datetime(6),
    "last_event_status_priority" int,
    "last_event_id"  bigint,
    "version"         int           NOT NULL DEFAULT 0,
    "creator"         varchar(64)   NOT NULL DEFAULT '',
    "create_time"     datetime      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"         varchar(64)   NOT NULL DEFAULT '',
    "update_time"     datetime      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted"         bit           NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_shipment_package_no" UNIQUE ("tenant_id", "shipment_id", "package_no", "deleted"),
    CONSTRAINT "uk_package_tracking" UNIQUE ("tenant_id", "carrier_id", "tracking_number", "deleted"),
    CONSTRAINT "chk_package_weight" CHECK ("weight" IS NULL OR "weight" >= 0),
    CONSTRAINT "chk_package_dimensions" CHECK (("length" IS NULL OR "length" >= 0)
        AND ("width" IS NULL OR "width" >= 0) AND ("height" IS NULL OR "height" >= 0))
);

CREATE TABLE IF NOT EXISTS "trade_shipment_leg"
(
    "id"                   bigint       NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "tenant_id"            bigint       NOT NULL,
    "shipment_id"          bigint       NOT NULL,
    "package_id"           bigint,
    "sequence_no"          int          NOT NULL,
    "leg_type"             varchar(20)  NOT NULL,
    "carrier_id"           bigint       NOT NULL,
    "provider_id"          bigint       NOT NULL,
    "service_level"        varchar(64),
    "tracking_number"      varchar(64),
    "pro_number"           varchar(64),
    "bol_number"           varchar(64),
    "origin_location"      varchar(256),
    "destination_location" varchar(256),
    "status"               varchar(32)  NOT NULL,
    "last_event_occurred_at" datetime(6),
    "last_event_status_priority" int,
    "last_event_id"        bigint,
    "started_at"           datetime,
    "completed_at"         datetime,
    "version"              int          NOT NULL DEFAULT 0,
    "creator"              varchar(64)  NOT NULL DEFAULT '',
    "create_time"          datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"              varchar(64)  NOT NULL DEFAULT '',
    "update_time"          datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted"              bit          NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_shipment_leg_sequence" UNIQUE ("tenant_id", "shipment_id", "sequence_no", "deleted")
);

CREATE TABLE IF NOT EXISTS "trade_tracking_status_mapping"
(
    "id"                         bigint       NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "tenant_id"                  bigint       NOT NULL,
    "provider_code"              varchar(32)  NOT NULL,
    "carrier_code"               varchar(32)  NOT NULL,
    "provider_status_normalized" varchar(128) NOT NULL,
    "standard_status"            varchar(32)  NOT NULL,
    "status_priority"            int          NOT NULL DEFAULT 0,
    "mapping_version"            varchar(32)  NOT NULL,
    "effective_at"               datetime(6)  NOT NULL,
    "creator"                    varchar(64)  NOT NULL DEFAULT '',
    "create_time"                datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"                    varchar(64)  NOT NULL DEFAULT '',
    "update_time"                datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted"                    bit          NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_tracking_status_mapping" UNIQUE
        ("tenant_id", "provider_code", "carrier_code", "provider_status_normalized", "mapping_version", "deleted")
);

CREATE INDEX IF NOT EXISTS "idx_tracking_status_mapping_effective"
    ON "trade_tracking_status_mapping" ("tenant_id", "provider_code", "carrier_code", "effective_at");

CREATE TABLE IF NOT EXISTS "trade_tracking_event"
(
    "id"                 bigint        NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "tenant_id"          bigint        NOT NULL,
    "shipment_id"        bigint        NOT NULL,
    "package_id"         bigint,
    "shipment_leg_id"    bigint,
    "provider_id"        bigint        NOT NULL,
    -- H2 VARCHAR equality is binary/case-sensitive, matching MySQL utf8mb4_bin in V017.
    "external_event_id"  varchar(128),
    "event_hash"         char(64),
    "standard_status"    varchar(32)   NOT NULL,
    "provider_status"    varchar(128)  NOT NULL,
    "provider_status_normalized" varchar(128) NOT NULL DEFAULT '',
    "mapping_version"    varchar(32),
    "mapping_effective_at" datetime(6),
    "mapping_known"      bit           NOT NULL DEFAULT FALSE,
    "transition_decision" varchar(20)   NOT NULL DEFAULT 'TIMELINE_ONLY',
    "previous_status"    varchar(32),
    "result_status"      varchar(32),
    "description"        varchar(1024),
    "location"           varchar(256),
    "occurred_at"        datetime(6)   NOT NULL,
    "occurred_timezone"  varchar(64),
    "received_at"        datetime(6)   NOT NULL,
    "raw_payload_ref"    varchar(256),
    "source"             varchar(20)   NOT NULL,
    "manual_operator_id" bigint,
    "manual_reason"      varchar(500),
    "request_trace_id"   varchar(64),
    "creator"            varchar(64)   NOT NULL DEFAULT '',
    "create_time"        datetime      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"            varchar(64)   NOT NULL DEFAULT '',
    "update_time"        datetime      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted"            bit           NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_tracking_event_external" UNIQUE ("tenant_id", "provider_id", "external_event_id", "deleted"),
    CONSTRAINT "uk_tracking_event_hash" UNIQUE ("tenant_id", "provider_id", "event_hash", "deleted"),
    CONSTRAINT "chk_tracking_event_identity" CHECK ("external_event_id" IS NOT NULL OR "event_hash" IS NOT NULL)
);

CREATE TABLE IF NOT EXISTS "trade_order_fulfillment_summary"
(
    "id"                       bigint       NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "tenant_id"                bigint       NOT NULL,
    "order_id"                 bigint       NOT NULL,
    "status"                   varchar(32)  NOT NULL,
    "shipment_count"           int          NOT NULL DEFAULT 0,
    "delivered_shipment_count" int          NOT NULL DEFAULT 0,
    "version"                  int          NOT NULL DEFAULT 0,
    "creator"                  varchar(64)  NOT NULL DEFAULT '',
    "create_time"              datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"                  varchar(64)  NOT NULL DEFAULT '',
    "update_time"              datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted"                  bit          NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_order_fulfillment_summary" UNIQUE ("tenant_id", "order_id", "deleted")
);

CREATE TABLE IF NOT EXISTS "trade_fulfillment_idempotency"
(
    "id"                   bigint       NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "tenant_id"            bigint       NOT NULL,
    "operation"            varchar(64)  NOT NULL,
    "idempotency_key_hash" char(64)     NOT NULL,
    "request_hash"         char(64)     NOT NULL,
    "resource_type"        varchar(32)  NOT NULL,
    "resource_id"          bigint,
    "status"               varchar(16)  NOT NULL,
    "expires_at"           datetime     NOT NULL,
    "creator"              varchar(64)  NOT NULL DEFAULT '',
    "create_time"          datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"              varchar(64)  NOT NULL DEFAULT '',
    "update_time"          datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted"              bit          NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_fulfillment_idempotency" UNIQUE ("tenant_id", "operation", "idempotency_key_hash", "deleted")
);

CREATE TABLE IF NOT EXISTS "trade_fulfillment_outbox_event"
(
    "id"              bigint       NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "tenant_id"       bigint       NOT NULL,
    "event_id"        char(36)     NOT NULL,
    "aggregate_type"  varchar(32)  NOT NULL,
    "aggregate_id"    bigint       NOT NULL,
    "event_type"      varchar(64)  NOT NULL,
    "payload"         varchar      NOT NULL,
    "status"          varchar(16)  NOT NULL,
    "attempt_count"   int          NOT NULL DEFAULT 0,
    "next_attempt_at" datetime     NOT NULL,
    "published_at"    datetime,
    "last_error_code" varchar(64),
    "creator"         varchar(64)  NOT NULL DEFAULT '',
    "create_time"     datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"         varchar(64)  NOT NULL DEFAULT '',
    "update_time"     datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted"         bit          NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_fulfillment_outbox_event_id" UNIQUE ("tenant_id", "event_id", "deleted")
);
